-- 146: Original BrillaPrep WASSCE BrillaPrep transitional Auto Mechanics beta content blueprint questions, part 4.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_146_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_146_guard;
INSERT INTO _migration_146_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_016' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_4' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is the main function of the engine oil pump?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Cool the lubricant by passing it through the radiator","B. Regulate oil viscosity as engine speed changes","C. Separate fuel that has entered the engine oil","D. Circulate oil under pressure to moving engine parts"]' AND q.correct_answer IS 'D' AND q.explanation IS 'The oil pump draws lubricant from the sump and supplies galleries feeding bearings and other moving surfaces to maintain a protective film. Therefore the correct answer is D: Circulate oil under pressure to moving engine parts.' AND q.difficulty IS 'easy' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_016' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_146_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_017' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_4' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is an engine thermostat used in the cooling system?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Control coolant flow so the engine reaches and maintains operating temperature","B. Increase coolant pressure whenever speed rises","C. Keep maximum radiator flow from a cold start","D. Switch the cooling fan on at every temperature"]' AND q.correct_answer IS 'A' AND q.explanation IS 'The thermostat restricts radiator flow when cold and opens near its rated temperature, balancing warm-up speed with heat rejection. Therefore the correct answer is A: Control coolant flow so the engine reaches and maintains operating temperature.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_017' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_146_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_018' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_4' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does a low oil-pressure warning require the driver to do?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Continue slowly until the next oil change","B. Stop the engine safely and investigate before continued operation","C. Increase engine speed to force the warning lamp off","D. Add coolant before checking lubricant level"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Insufficient oil pressure can damage bearings within seconds, so continuing to run the engine risks severe seizure or wear. Therefore the correct answer is B: Stop the engine safely and investigate before continued operation.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_018' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_146_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_019' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_4' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why must a hot pressurised radiator cap not be removed suddenly?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Air entry will immediately seize the water pump","B. Coolant pressure will force oil from the bearings","C. Escaping pressure can release boiling coolant and cause burns","D. The thermostat will remain permanently closed"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Cooling-system pressure raises coolant boiling point; sudden opening can flash hot coolant into steam and eject it violently. Therefore the correct answer is C: Escaping pressure can release boiling coolant and cause burns.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_4' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_019' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_146_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_auto_mech_b002_020' AND NOT (q.topic_id IS 'topic_was_auto_mech_b002_4' AND q.subject_id IS 'subj_wassce_auto_mech' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Which fault can cause both overheating and poor cabin-heater output?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A thermostat stuck partly open","B. A cooling fan that runs continuously","C. Coolant mixed at the correct concentration","D. Low coolant level that prevents proper circulation"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Low coolant may leave passages and the heater core partly empty, reducing heat transfer while allowing engine hot spots and overheating. Therefore the correct answer is D: Low coolant level that prevents proper circulation.' AND q.difficulty IS 'medium' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_auto_mech_b002_4' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_auto_mech_b002_020' AND NOT (r.batch_id IS 'wassce-technical-beta-002' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Auto Mechanics practice aligned to WAEC Ghana examiner evidence; not official WAEC examination material or a copied past paper.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2025/05/CHIEF-EXAMINERS-REPORTS.-WASSCE-SC-2023.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
